// timeoutDiagnostic builds the label and supporting rows for a
// context.DeadlineExceeded failure from the user-set summary timeout.
// It reads captured state from attempt to attribute the failure to a
// specific subprocess phase (streaming providers) or to "no output"
// vs "produced output then killed" (non-streaming providers).
func timeoutDiagnostic(err error, deadline time.Duration, attempt *summaryProgressWriter) (string, []explainRow) {
    deadlineStr := formatSummaryTimeout(deadline)

    if attempt != nil && attempt.streamed {
        switch {
        case !attempt.phasesReached[agent.PhaseConnecting]:
            return "Timed out after " + deadlineStr + ": provider never sent its request",
                []explainRow{
                    {Label: "cause", Value: "the provider CLI may be stalled before subprocess startup"},
                    {Label: "try", Value: "run the provider CLI directly to confirm it works"},
                }
        case !attempt.phasesReached[agent.PhaseFirstToken]:
            return "Timed out after " + deadlineStr + ": provider sent request but received no response",
                []explainRow{
                    {Label: "cause", Value: "network/firewall, provider API degraded, or auth check stuck"},
                    {Label: "try", Value: "check connectivity to the provider, then retry"},
                }
        case !attempt.phasesReached[agent.PhaseDone]:
            return "Timed out after " + deadlineStr + ": model responded but did not finish",
                []explainRow{
                    {Label: "cause", Value: "transcript may be too large for the chosen cap, or model is slow"},
                    {Label: "try", Value: "raise --summary-timeout-seconds or pick a faster model"},
                }
        }
    }

    // Non-streaming provider, or streaming attempt with no events captured.
    var stderr string
    var stdoutBytes int
    var failure *TextGenerationFailure
    if errors.As(err, &failure) {
        stderr = strings.TrimSpace(failure.Stderr)
        stdoutBytes = failure.StdoutBytes
    }

    if stdoutBytes == 0 {
        rows := []explainRow{
            {Label: "cause", Value: "provider CLI produced no output (likely network/auth/CLI path issue)"},
            {Label: "try", Value: "run the provider CLI directly to confirm it works"},
        }
        if stderr != "" {
            rows = append(rows, explainRow{Label: "stderr", Value: stderr})
        }
        return "Timed out after " + deadlineStr + ": provider produced no output", rows
    }

    rows := []explainRow{
        {Label: "cause", Value: "provider was generating output but did not finish before cap"},
        {Label: "try", Value: "raise --summary-timeout-seconds"},
    }
    if stderr != "" {
        rows = append(rows, explainRow{Label: "stderr", Value: stderr})
    }
    return "Timed out after " + deadlineStr + ": provider was generating output when killed", rows
}
```

