```go
package summarize

import "strings"

// FailureCategory identifies the broad class of a non-streaming text-generation
// failure based on substring patterns in captured stderr. Categories are
// advisory; the raw stderr is always surfaced alongside any classification so
// users can verify the call.
type FailureCategory string

const (
	FailureCategoryUnknown       FailureCategory = ""
	FailureCategoryNetwork       FailureCategory = "network"
	FailureCategoryAuth          FailureCategory = "auth"
	FailureCategoryRateLimit     FailureCategory = "rate_limit"
	FailureCategoryServerError   FailureCategory = "server_error"
	FailureCategoryModelNotFound FailureCategory = "model_not_found"
)

// ClassifyStderr inspects captured subprocess stderr against known phrases
// and returns a category plus a user-facing hint. Returns FailureCategoryUnknown
// and an empty hint when no pattern matches.
//
// All matching is substring + case-insensitive. Phrases were selected from
// real CLI failure output of Codex, Cursor, Copilot, and Gemini at the time
// of writing. Patterns may rot over time as CLIs change their stderr; the
// raw stderr is always shown to users so misclassification is recoverable.
func ClassifyStderr(stderr string) (FailureCategory, string) {
	lower := strings.ToLower(stderr)
	switch {
	case containsAnyLower(lower, "connection refused", "could not resolve", "no route to host",
		"network unreachable", "name or service not known", "dial tcp"):
		return FailureCategoryNetwork, "couldn't reach provider API -- check network/VPN"
	case containsAnyLower(lower, "unauthorized", "401", "not logged in", "authentication failed", "auth token"):
		return FailureCategoryAuth, "provider rejected credentials -- re-authenticate with the provider CLI"
	case containsAnyLower(lower, "rate limit", "429", "quota exceeded", "too many requests"):
		return FailureCategoryRateLimit, "provider rate-limit -- wait and retry"
	case containsAnyLower(lower, "service unavailable", "503", "502", "bad gateway", "internal server error", "500"):
		return FailureCategoryServerError, "provider API degraded -- try again shortly"
	case containsAnyLower(lower, "model not found", "invalid model", "unknown model"):
		return FailureCategoryModelNotFound, "model rejected -- check --model flag or settings"
	default:
		return FailureCategoryUnknown, ""
	}
}

// containsAnyLower returns true if lower (which the caller has already
// lowercased) contains any of the given substrings. Substrings should
// already be lowercase.
func containsAnyLower(lower string, substrings ...string) bool {
	for _, s := range substrings {
		if strings.Contains(lower, s) {
			return true
		}
	}
	return false
}
```

