func TestSummaryProgressWriter_FirstTokenWithoutOptionalFields(t *testing.T) {
    t.Parallel()

    var buf bytes.Buffer
    attempt := newSummaryAttempt("gemini-cli", 0)
    pw := newSummaryProgressWriter(&buf, attempt)

