```go
package codex

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// streamBufferMax bounds a single NDJSON line. Codex envelopes can be large
// (init events may carry the full tool list), so we lift the default scanner
// limit substantially.
const streamBufferMax = 4 * 1024 * 1024 // 4 MiB

// parseCodexStream consumes `codex exec --json` NDJSON output, dispatches
// progress callbacks, and returns the final agent_message text. Returns
// an error if the stream ends without a turn.completed event or if a
// turn.failed event is observed.
func parseCodexStream(stdout io.Reader, progress agent.ProgressFn) (string, error) {
	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 64*1024), streamBufferMax)

	var (
		resultText      string
		firstTokenFired bool
		sawTurnComplete bool
		usage           *codexStreamUsage
		malformed       int
	)

	dispatch := func(p agent.GenerationProgress) {
		if progress != nil {
			progress(p)
		}
	}

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var ev codexStreamEvent
		if err := json.Unmarshal(line, &ev); err != nil {
			malformed++
			continue
		}

		switch ev.Type {
		case "turn.started":
			dispatch(agent.GenerationProgress{Phase: agent.PhaseConnecting})

		case "item.completed":
			if ev.Item != nil && ev.Item.Type == "agent_message" {
				if !firstTokenFired {
					firstTokenFired = true
					dispatch(agent.GenerationProgress{Phase: agent.PhaseFirstToken})
				}
				// Use the LAST agent_message as the final result. Codex emits
				// one per assistant turn; for a summary prompt there's typically
				// exactly one, but if the model produces multiple (e.g. it
				// explained then re-emitted) the last is what matches what
				// the user would see.
				resultText = ev.Item.Text
			}

		case "turn.completed":
			sawTurnComplete = true
			usage = ev.Usage

		case "turn.failed", "error":
			detail := "unspecified error"
			if len(line) > 0 {
				detail = string(line)
			}
			return "", fmt.Errorf("codex turn failed: %s", detail)
		}
	}
	if err := scanner.Err(); err != nil {
		return "", fmt.Errorf("reading codex stream: %w", err)
	}
	if !sawTurnComplete {
		return "", errors.New("codex stream ended without a turn.completed event")
	}
	if resultText == "" {
		return "", errors.New("codex stream produced no agent_message")
	}
	if progress != nil {
		done := agent.GenerationProgress{Phase: agent.PhaseDone}
		if usage != nil {
			done.OutputTokens = usage.OutputTokens
			done.InputTokens = usage.InputTokens
			done.CachedInputTokens = usage.CachedInputTokens
		}
		dispatch(done)
	}
	_ = malformed // malformed counter reserved for future logging if needed
	return resultText, nil
}

// GenerateTextStreaming runs `codex exec --skip-git-repo-check --json -` and
// dispatches progress events to the optional callback. Implements
// agent.StreamingTextGenerator.
//
// If the codex CLI rejects the --json flag (older version), the template
// signals ErrUnrecognizedStreamingFlag and the caller falls back to the
// non-streaming GenerateText path.
func (c *CodexAgent) GenerateTextStreaming(
	ctx context.Context,
	prompt, model string,
	progress agent.ProgressFn,
) (string, error) {
	tmpl := &agent.StreamingGeneratorTemplate{
		AgentName:                 "codex",
		DisplayName:               "codex",
		BuildCmd:                  c.buildStreamCmd,
		Parser:                    parseCodexStream,
		LooksLikeUnrecognizedFlag: looksLikeCodexUnrecognizedFlag,
	}

	result, err := tmpl.Generate(ctx, prompt, model, progress)
	if errors.Is(err, agent.ErrUnrecognizedStreamingFlag) {
		return c.GenerateText(ctx, prompt, model)
	}
	return result, err
}

func (c *CodexAgent) buildStreamCmd(ctx context.Context, prompt, model string) *exec.Cmd {
	commandRunner := c.CommandRunner
	if commandRunner == nil {
		commandRunner = exec.CommandContext
	}
	args := []string{"exec", "--skip-git-repo-check", "--json"}
	if model != "" {
		args = append(args, "--model", model)
	}
	args = append(args, "-")
	cmd := commandRunner(ctx, "codex", args...)
	cmd.Stdin = strings.NewReader(prompt)
	return cmd
}

// looksLikeCodexUnrecognizedFlag returns true if codex stderr indicates the
// --json flag was rejected. Mirrors claudecode's pattern: AND-logic between
// a rejection phrase and a streaming-flag name.
func looksLikeCodexUnrecognizedFlag(stderr string) bool {
	lower := strings.ToLower(stderr)
	hasRejectPhrase := strings.Contains(lower, "unrecognized option") ||
		strings.Contains(lower, "unknown flag") ||
		strings.Contains(lower, "unknown option") ||
		strings.Contains(lower, "invalid option")
	if !hasRejectPhrase {
		return false
	}
	return strings.Contains(lower, "json") || strings.Contains(lower, "exec")
}
```

